if(str_starts_with($path,'/api/v1/')){if(!isset($_SERVER['HTTP_AUTHORIZATION']))ManagerSession::start();Http::serve($db,$f['club'],$f['origin'],$f['root'].'/media',$f['root'].'/documents',$_SESSION['auth_token']??null,$_SESSION['csrf']??null);exit;}
